contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public entry: try withdrawing `amount` and assert relation between revert and c balance
    function run(uint256 amount) public payable {
        // no precondition needed
        // record balance before the attempted withdraw
        uint256 beforeBalance = address(c).balance;

        // Attempt withdraw and record whether it reverted
        bool reverted;
        c.withdraw(amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 afterBalance = address(c).balance;

        // General rule: if withdraw reverted, c's balance is unchanged; if it succeeded, c's balance decreased by exactly amount
        assert(reverted ? afterBalance == beforeBalance : (beforeBalance >= amount && afterBalance + amount == beforeBalance));
    }

    receive() external payable { }
}

